import {renderView,section,list,button,selectInput} from '../ui/view.js';import {EditorService} from '../services/editor-service.js';import {loadJson} from './literary-core-config-loader.js';import {el} from './literary-core-dom.js';import {notify} from './literary-core-notifications.js';
export async function continuityView(){const [r,defs]=await Promise.all([EditorService.issues(),loadJson('json/issue-types.json')]);const issues=r.issues||[],body=document.createDocumentFragment();const controls=section('Analyze',[button('Run continuity scan',async()=>{await EditorService.scan({scopeType:'project'});notify('Continuity scan completed.');continuityView();})]);body.append(controls);body.append(section('Issue Center',[list(issues,issue=>{const a=el('article',{},[el('h3',{text:issue.title||issue.issueClass||issue.type||'Continuity issue'}),el('p',{text:issue.explanation||issue.description||issue.message||''}),el('p',{text:`Severity: ${issue.severity||'—'} · Confidence: ${issue.confidence??'—'}`})]);if(issue.evidence?.length||issue.evidence) a.append(el('details',{},[el('summary',{text:'Evidence'}),el('pre',{text:JSON.stringify(issue.evidence,null,2)})]));const actions=el('div');defs.actions.forEach(act=>actions.append(button(act.label,async()=>{await EditorService.action(issue.id,act.id);notify(`${act.label} recorded.`);continuityView();})));a.append(actions);return a;},{empty:'No continuity issues are currently recorded.'})]));renderView('Continuity Center',{description:'Review evidence-backed contradictions and editorial concerns without silently changing canon.',body});}
